const fs = require('fs');
const path = require('path');
const pkg = require('../package.json');

// build-info.json is generated by the CI build job; fall back to local values in dev.
function getBuildInfo(file = path.join(__dirname, '..', 'build-info.json')) {
  try {
    return JSON.parse(fs.readFileSync(file, 'utf8'));
  } catch {
    return { version: pkg.version, commit: 'local', builtAt: null };
  }
}

module.exports = { getBuildInfo };
